arguments.file_text:
namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    [StringLength(20)]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and fundamental forces." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and communication." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory programming and researches computer science education.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures including arrays, linked lists, trees, and graphs. Analysis of algorithm complexity.", Credits = 4, Schedule = "Tue/Thu 10:00–11:15 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm design and has published extensively on graph theory.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, Code = "CS 301", Title = "Database Systems", Description = "Relational database design, SQL, normalization, and transaction management.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Gonzalez", InstructorBio = "Dr. Gonzalez worked in industry for 10 years before joining academia, specializing in distributed databases.", IsFeatured = false },
            new() { Id = 4, DepartmentId = 1, Code = "CS 401", Title = "Software Engineering", Description = "Software development methodologies, design patterns, testing, and project management.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim brings real-world experience from leading engineering teams at major tech companies.", IsFeatured = false },
            new() { Id = 5, DepartmentId = 2, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson is an award-winning educator known for making calculus accessible to all students.", IsFeatured = true },
            new() { Id = 6, DepartmentId = 2, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Alan Torres", InstructorBio = "Dr. Torres researches numerical linear algebra and its applications in machine learning.", IsFeatured = false },
            new() { Id = 7, DepartmentId = 2, Code = "MATH 301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Lisa Patel", InstructorBio = "Dr. Patel is a statistician with expertise in Bayesian methods and data science.", IsFeatured = false },
            new() { Id = 8, DepartmentId = 3, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. David Lee", InstructorBio = "Dr. Lee is an experimental physicist whose research focuses on condensed matter physics.", IsFeatured = true },
            new() { Id = 9, DepartmentId = 3, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM + Lab Fri 2:00–4:00 PM", InstructorName = "Dr. Karen Wright", InstructorBio = "Dr. Wright researches electromagnetic wave propagation and antenna design.", IsFeatured = false },
            new() { Id = 10, DepartmentId = 4, Code = "ENG 101", Title = "Composition and Rhetoric", Description = "Develop college-level writing skills through essays, research papers, and peer review.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Prof. Michael Brown", InstructorBio = "Prof. Brown is a published author who has taught writing at the university level for over 20 years.", IsFeatured = false },
            new() { Id = 11, DepartmentId = 4, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", InstructorName = "Dr. Rachel Adams", InstructorBio = "Dr. Adams specializes in 20th-century American fiction and has published three books on the subject.", IsFeatured = true },
            new() { Id = 12, DepartmentId = 5, Code = "HIST 101", Title = "World History I", Description = "Survey of world history from ancient civilizations to 1500 CE.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Thomas Grant", InstructorBio = "Dr. Grant is an archaeologist and historian specializing in ancient Mediterranean civilizations.", IsFeatured = false },
            new() { Id = 13, DepartmentId = 5, Code = "HIST 220", Title = "Modern European History", Description = "European history from the Enlightenment to the present day, covering political, social, and cultural developments.", Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM", InstructorName = "Dr. Anna Schmidt", InstructorBio = "Dr. Schmidt is a specialist in 19th-century European intellectual history.", IsFeatured = false },
        };
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses() => _courses;

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

