@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="container">
    <div class="hero">
        <h1>University Course Catalog</h1>
        <p class="lead">Explore our departments and courses. Find the right classes for your academic journey.</p>
        <a href="/courses" class="btn btn-primary btn-lg">Browse All Courses</a>
    </div>

    <section class="mt-5">
        <h2>Featured Courses</h2>
        <div class="row mt-3">
            @foreach (var course in featuredCourses)
            {
                <div class="col-md-6 col-lg-4 mb-4">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@course.Code</h5>
                            <h6 class="card-subtitle mb-2 text-muted">@course.Title</h6>
                            <p class="card-text">@course.Credits credits &bull; @course.InstructorName</p>
                            <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>

    <section class="mt-5">
        <h2>Departments</h2>
        <div class="row mt-3">
            @foreach (var dept in departments)
            {
                <div class="col-md-6 col-lg-4 mb-3">
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">@dept.Name</h5>
                            <p class="card-text text-muted">@dept.Description</p>
                            <a href="/courses?departmentId=@dept.Id" class="btn btn-outline-secondary btn-sm">View Courses</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>
</div>

@code {
    private IReadOnlyList<Course> featuredCourses = [];
    private IReadOnlyList<Department> departments = [];

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Course Catalog - Browse Courses</PageTitle>

<div class="container">
    <h1>Course Catalog</h1>

    <form method="get" class="row g-3 mb-4 mt-2">
        <div class="col-md-6">
            <input type="text" name="search" value="@Search" class="form-control" placeholder="Search courses, instructors..." />
        </div>
        <div class="col-md-4">
            <select name="departmentId" class="form-select">
                <option value="">All Departments</option>
                @foreach (var dept in departments)
                {
                    <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button type="submit" class="btn btn-primary w-100">Filter</button>
        </div>
    </form>

    @if (courses.Count == 0)
    {
        <div class="alert alert-info">No courses found matching your criteria.</div>
    }
    else
    {
        <p class="text-muted">Showing @courses.Count course(s)</p>
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead>
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Credits</th>
                        <th>Instructor</th>
                        <th>Schedule</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in courses)
                    {
                        <tr>
                            <td><strong>@course.Code</strong></td>
                            <td>@course.Title</td>
                            <td>@course.Credits</td>
                            <td>@course.InstructorName</td>
                            <td>@course.Schedule</td>
                            <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private IReadOnlyList<Department> departments = [];
    private IReadOnlyList<Course> courses = [];

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        courses = CatalogService.SearchCourses(Search, DepartmentId);
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <div class="container">
        <div class="alert alert-warning mt-4">
            <h4>Course Not Found</h4>
            <p>The requested course could not be found.</p>
            <a href="/courses" class="btn btn-primary">Back to Catalog</a>
        </div>
    </div>
}
else
{
    <PageTitle>@course.Code - @course.Title</PageTitle>
    <div class="container">
        <nav aria-label="breadcrumb" class="mt-3">
            <ol class="breadcrumb">
                <li class="breadcrumb-item"><a href="/">Home</a></li>
                <li class="breadcrumb-item"><a href="/courses?departmentId=@course.DepartmentId">@department?.Name</a></li>
                <li class="breadcrumb-item active">@course.Code</li>
            </ol>
        </nav>

        <div class="row">
            <div class="col-lg-8">
                <h1>@course.Code: @course.Title</h1>
                <p class="lead">@course.Description</p>

                <div class="card mt-4">
                    <div class="card-body">
                        <h5 class="card-title">Course Details</h5>
                        <dl class="row mb-0">
                            <dt class="col-sm-3">Credits</dt>
                            <dd class="col-sm-9">@course.Credits</dd>

                            <dt class="col-sm-3">Schedule</dt>
                            <dd class="col-sm-9">@course.Schedule</dd>

                            <dt class="col-sm-3">Department</dt>
                            <dd class="col-sm-9">@department?.Name</dd>
                        </dl>
                    </div>
                </div>
            </div>

            <div class="col-lg-4 mt-4 mt-lg-0">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">Instructor</h5>
                        <h6>@course.InstructorName</h6>
                        <p class="text-muted">@course.InstructorBio</p>
                    </div>
                </div>

                <div class="mt-3">
                    <a href="/enroll?courseId=@course.Id" class="btn btn-success w-100">Request Enrollment</a>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;
    private Department? department;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
        if (course is not null)
        {
            department = CatalogService.GetDepartment(course.DepartmentId);
        }
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<div class="container">
    <h1>Enrollment Request</h1>
    <p class="text-muted">Submit your enrollment request below. You will receive confirmation via your university email.</p>

    @if (submitted)
    {
        <div class="alert alert-success mt-4">
            <h4>Request Submitted!</h4>
            <p>Your enrollment request for <strong>@selectedCourseName</strong> has been received. You will be notified of your enrollment status.</p>
            <a href="/courses" class="btn btn-primary">Back to Catalog</a>
        </div>
    }
    else
    {
        <form method="post" @formname="enrollment" @onsubmit="HandleSubmit" class="mt-4" style="max-width: 600px;">
            <AntiforgeryToken />

            <div class="mb-3">
                <label for="studentName" class="form-label">Full Name</label>
                <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" class="form-control" required />
                @if (errors.ContainsKey(nameof(Model.StudentName)))
                {
                    <div class="text-danger mt-1">@errors[nameof(Model.StudentName)]</div>
                }
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control" placeholder="e.g., STU-12345" required />
                @if (errors.ContainsKey(nameof(Model.StudentId)))
                {
                    <div class="text-danger mt-1">@errors[nameof(Model.StudentId)]</div>
                }
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <select id="courseId" name="Model.CourseId" class="form-select" required>
                    <option value="0">-- Select a course --</option>
                    @foreach (var course in courses)
                    {
                        <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.Code - @course.Title</option>
                    }
                </select>
                @if (errors.ContainsKey(nameof(Model.CourseId)))
                {
                    <div class="text-danger mt-1">@errors[nameof(Model.CourseId)]</div>
                }
            </div>

            <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
            <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
        </form>
    }
</div>

@code {
    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    private IReadOnlyList<Course> courses = [];
    private Dictionary<string, string> errors = new();
    private bool submitted;
    private string selectedCourseName = string.Empty;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        errors.Clear();

        var validationResults = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        var context = new System.ComponentModel.DataAnnotations.ValidationContext(Model);
        if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(Model, context, validationResults, true))
        {
            foreach (var result in validationResults)
            {
                foreach (var member in result.MemberNames)
                {
                    if (!errors.ContainsKey(member))
                    {
                        errors[member] = result.ErrorMessage ?? "Invalid value.";
                    }
                }
            }
            return;
        }

        var course = CatalogService.GetCourse(Model.CourseId);
        selectedCourseName = course is not null ? $"{course.Code} - {course.Title}" : "Unknown Course";
        submitted = true;
    }
}

